<?php
require dirname(__DIR__) . '/config.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';
 try{
  if($action==='delete'){ $id=(int)$_POST['id'];$s=db()->prepare('SELECT image_path FROM projects WHERE id=?');$s->execute([$id]);delete_upload($s->fetchColumn()?:null);db()->prepare('DELETE FROM projects WHERE id=?')->execute([$id]);flash('Project deleted.');}
  else { $id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');if($title==='')throw new RuntimeException('Project title is required.');$desc=trim($_POST['description']??'');$link=trim($_POST['website_url']??'');if($link!==''&&!filter_var($link,FILTER_VALIDATE_URL))throw new RuntimeException('Enter a valid project URL.');$order=(int)($_POST['sort_order']??0);
   $img=upload_file('image','projects',['image/jpeg'=>['jpg'],'image/png'=>['png'],'image/webp'=>['webp']],5000000);
   if($id){$q=db()->prepare('SELECT image_path FROM projects WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn();if($img)delete_upload($old?:null);$sql='UPDATE projects SET title=?,description=?,website_url=?,sort_order=?'.($img?',image_path=?':'').' WHERE id=?';$args=[$title,$desc,$link,$order];if($img)$args[]=$img;$args[]=$id;db()->prepare($sql)->execute($args);}
   else db()->prepare('INSERT INTO projects(title,description,website_url,sort_order,image_path) VALUES(?,?,?,?,?)')->execute([$title,$desc,$link,$order,$img]);
   flash('Project saved.');
  }
 }catch(Throwable $e){flash($e->getMessage(),'danger');}redirect('admin/projects.php');
}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM projects WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$rows=db()->query('SELECT * FROM projects ORDER BY sort_order,id DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projects</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body class="dashboard"><div class="admin-shell"><?php include 'nav.php';?><main class="admin-main"><div class="admin-top"><div><span class="eyebrow">PORTFOLIO CONTENT</span><h1>Projects</h1></div></div><?php show_flash();?><div class="admin-panel mb-4"><h2><?=$edit?'Edit project':'Add a project'?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="row g-3"><div class="col-md-6"><label>Project title</label><input class="form-control" name="title" required value="<?=e($edit['title']??'')?>"></div><div class="col-md-6"><label>Website link</label><input class="form-control" name="website_url" type="url" placeholder="https://" value="<?=e($edit['website_url']??'')?>"></div><div class="col-12"><label>Description</label><textarea class="form-control" name="description" rows="3"><?=e($edit['description']??'')?></textarea></div><div class="col-md-6"><label>Project image (JPG/PNG/WEBP, max 5 MB)</label><input class="form-control" type="file" name="image" accept=".jpg,.jpeg,.png,.webp"></div><div class="col-md-3"><label>Display order</label><input class="form-control" type="number" name="sort_order" value="<?=(int)($edit['sort_order']??0)?>"></div><div class="col-12"><button class="btn btn-primary">Save project</button><?php if($edit):?> <a class="btn btn-outline-light" href="projects.php">Cancel</a><?php endif;?></div></div></form></div>
<div class="admin-panel"><h2>All projects</h2><div class="table-responsive"><table class="table table-dark table-hover"><thead><tr><th>Project</th><th>Link</th><th>Order</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?php if($r['website_url']):?><a target="_blank" href="<?=e($r['website_url'])?>">Visit ↗</a><?php endif;?></td><td><?=$r['sort_order']?></td><td><a href="?edit=<?=$r['id']?>">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Delete this project?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-link text-danger p-0 ms-2">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></main></div></body></html>
